//! Generated by `rosezm export rust-desktop` - the app in a native window.
//!
//! One binary, three halves:
//!
//!   * the STATIC half - the built site, embedded with `include_bytes!` and
//!     served to the WebView over a loopback HTTP server;
//!   * the BUSINESS half - the Rust kernel, answering `POST /kernel/call`;
//!   * the NATIVE half - `POST /native/call`, the capability contract
//!     (`useNative(...)`) answered by the OS: the window, the file system,
//!     the dialogs, the notifications, the clipboard.
//!
//! tao owns the window, wry draws the site, the kernel runs in-process: no
//! Node, no sidecar, no external server.

use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicU8, Ordering};
use std::sync::mpsc::{channel, Sender};
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

use serde_json::{json, Value};
use tao::dpi::LogicalSize;
use tao::event::{Event, StartCause, WindowEvent};
use tao::event_loop::{ControlFlow, EventLoop, EventLoopBuilder, EventLoopProxy, EventLoopWindowTarget};
use tao::window::{Window, WindowBuilder};
use wry::WebViewBuilder;

mod assets;
mod config;

/// What the OS has to answer. The window belongs to the event loop's thread,
/// so the request thread sends one of these and waits for the answer - the
/// same shape a preload's IPC call has in every other rosezm shell.
enum NativeEvent {
    /// The window controls the page draws (minimize / maximize / close ...).
    WindowControl { action: String, from: u64, reply: Sender<Value> },
    /// The page's own theme switch drives the window's appearance, so the
    /// material behind the page follows it (a dark page behind a light rail
    /// is the bug the Electron shell fixed the same way).
    Theme { source: String, reply: Sender<Value> },
    /// A route opens in its own OS window.
    OpenWindow { route: String, title: String, width: f64, height: f64, always_on_top: bool, reply: Sender<Value> },
    /// WeChat-style login: open the editor window at the configured size and
    /// close the small login window that asked for it.
    SwapWindow { from: u64, reply: Sender<Value> },
    /// The login window grows (register) or shrinks back (login).
    ResizeWindow { from: u64, width: f64, height: f64, resizable: bool, reply: Sender<Value> },
    /// A message to every OTHER window, delivered as a DOM CustomEvent.
    Post { data: Value, from: u64, reply: Sender<bool> },
    /// The OS context menu, answered with the id that was clicked.
    ContextMenu { items: Vec<Value>, x: Option<f64>, y: Option<f64>, reply: Sender<Option<String>> },
    /// The system file pickers.
    PickDirectory { title: String, reply: Sender<Option<Vec<String>>> },
    PickFile { title: String, multi: bool, filters: Vec<(String, Vec<String>)>, reply: Sender<Option<Vec<String>>> },
    /// The system message box.
    Modal { title: String, message: String, buttons: Vec<String>, reply: Sender<bool> },
    /// The system clipboard.
    ClipboardRead { reply: Sender<Option<String>> },
    ClipboardWrite { text: String, reply: Sender<bool> },
    /// A system notification.
    Notify { title: String, body: String, reply: Sender<bool> },
    /// Where AppKit actually put the native traffic lights. AppKit calls must
    /// run on the main thread, so a request asks the event loop to measure.
    TrafficLights { from: u64, reply: Sender<Value> },
    /// Set the native window title (document name + dirty marker).
    SetWindowTitle { from: u64, title: String, reply: Sender<bool> },
}

// tao's event loop carries a typed user event; the proxy only needs the
// payload to be 'static, so no extra trait is implemented here.

/// The state every request thread shares with the event loop.
struct Shared {
    /// 0 = unknown, 1 = light, 2 = dark. The OS truth, refreshed whenever the
    /// window takes focus or the system appearance changes.
    dark: AtomicU8,
    /// The folder the user opened. Every file operation is scoped to it: the
    /// renderer never sees the rest of the disk.
    root: Mutex<Option<PathBuf>>,
    /// Files the user picked one by one - readable, never their neighbours.
    picked: Mutex<Vec<PathBuf>>,
}

impl Shared {
    fn new() -> Self {
        Shared { dark: AtomicU8::new(0), root: Mutex::new(None), picked: Mutex::new(Vec::new()) }
    }

    fn is_dark(&self) -> bool {
        self.dark.load(Ordering::Relaxed) == 2
    }

    fn set_dark(&self, dark: bool) {
        self.dark.store(if dark { 2 } else { 1 }, Ordering::Relaxed);
    }
}

/// One window of the app: the OS window, the WebView drawing the site in it,
/// and the route it shows (the route is how a window is addressed).
struct WindowRec {
    id: u64,
    route: String,
    window: Window,
    webview: wry::WebView,
}

fn main() {
    // A STABLE origin is essential: localStorage is scoped to
    // scheme://host:port. config::PORT is derived from APP_ID so sessions,
    // remembered logins and workspace history survive a relaunch. Only a
    // collision (another process owns the port) falls back to an ephemeral one.
    let listener = TcpListener::bind(("127.0.0.1", config::PORT))
        .unwrap_or_else(|_| TcpListener::bind("127.0.0.1:0").expect("bind localhost"));
    let port = listener.local_addr().expect("addr").port();
    let index: HashMap<&'static str, &'static [u8]> = assets::ASSETS.iter().copied().collect();
    let index = Arc::new(index);
    let shared = Arc::new(Shared::new());

    let event_loop = EventLoopBuilder::<NativeEvent>::with_user_event().build();
    let proxy = event_loop.create_proxy();

    // The server half: the static site, the kernel and the capability bridge,
    // one loopback listener, one thread per request.
    {
        let index = Arc::clone(&index);
        let shared = Arc::clone(&shared);
        let proxy = proxy.clone();
        std::thread::spawn(move || {
            for stream in listener.incoming() {
                let Ok(stream) = stream else { continue };
                let index = Arc::clone(&index);
                let shared = Arc::clone(&shared);
                let proxy = proxy.clone();
                std::thread::spawn(move || {
                    let _ = serve(stream, &index, &shared, &proxy, port);
                });
            }
        });
    }

    let window = build_window(&event_loop);
    let start_route = if config::START_ROUTE.is_empty() { "/".to_string() } else { config::START_ROUTE.to_string() };
    // The boot cover must be attached AFTER build_webview: wry replaces the
    // window's content view, which would take an earlier cover with it.
    let cover_slot: Arc<Mutex<Option<usize>>> = Arc::new(Mutex::new(None));
    let cover_slot_loaded = Arc::clone(&cover_slot);
    let webview = build_webview(&window, port, &start_route, {
        Some(Box::new(move || {
            #[cfg(target_os = "macos")]
            {
                if let Some(ptr) = *cover_slot_loaded.lock().unwrap() {
                    let view: &objc2_app_kit::NSView = unsafe { &*(ptr as *const objc2_app_kit::NSView) };
                    view.removeFromSuperview();
                }
                *cover_slot_loaded.lock().unwrap() = None;
            }
        }) as Box<dyn Fn() + 'static>)
    });
    #[cfg(target_os = "macos")]
    {
        if let Some(cover) = install_boot_cover(&window) {
            let ptr = objc2::rc::Retained::as_ptr(&cover) as usize;
            *cover_slot.lock().unwrap() = Some(ptr);
            std::mem::forget(cover);
        }
    }
    // wry replaces the window's content view; the material must be attached to
    // that NEW view, or it is thrown away with the old one.
    apply_material(&window);
    set_window_id(&webview, 1);
    let shared_for_loop = Arc::clone(&shared);
    let mut windows: Vec<WindowRec> = vec![WindowRec { id: 1, route: start_route.clone(), window, webview }];
    let mut centred = false;
    let mut was_full = false;

    event_loop.run(move |event, elwt, control_flow| {
        *control_flow = ControlFlow::Wait;
        match event {
            Event::NewEvents(StartCause::Init) => {
                // The address the shell serves on: the window points at it, and
                // it is the only way in for the capability bridge.
                println!("{} {} - window up on http://127.0.0.1:{}", config::APP_NAME, config::APP_VERSION, port);
            }
            Event::WindowEvent { event: WindowEvent::Resized(_), .. } => {
                // Centre once, on the first real size: before the first paint
                // outer_size is the builder's guess, not the OS window.
                if config::CENTER && !centred {
                    if let Some(rec) = windows.first() {
                        center_window(&rec.window);
                    }
                    centred = true;
                }
                // Native fullscreen (green button) is not a tao state change;
                // AppKit's styleMask is the truth. Also tell the page so it
                // stops reserving the traffic-light corner.
                for rec in &windows {
                    let before = was_full;
                    sync_fullscreen_toolbar(&rec.window, &mut was_full);
                    if before != was_full {
                        let script = format!(
                            "window.dispatchEvent(new CustomEvent('rosezm:window-event', {{ detail: {{ type: 'window-state', fullscreen: {} }} }}));",
                            was_full
                        );
                        let _ = rec.webview.evaluate_script(&script);
                    }
                }
            }
            Event::UserEvent(ev) => {
                // An AppKit animated resize delivers its Resized event only
                // AFTER the animation; that would be the "first" Resize and
                // centre the window to the screen, yanking it mid-expand.
                if matches!(&ev, NativeEvent::ResizeWindow { .. }) { centred = true; }
                handle_native(ev, elwt, port, &mut windows, &shared_for_loop);
            }
            Event::WindowEvent { event: WindowEvent::CloseRequested, window_id, .. } => {
                // Drop only the window that asked to close; the app exits when
                // the last one goes (login window → editor swap keeps it alive).
                windows.retain(|w| w.window.id() != window_id);
                if windows.is_empty() { *control_flow = ControlFlow::Exit; }
            }
            Event::WindowEvent { event: WindowEvent::Focused(true), .. } => {
                // The OS appearance is the truth about dark mode - ask again
                // whenever the window takes focus.
                refresh_theme(&windows, &shared_for_loop);
            }
            Event::WindowEvent { event: WindowEvent::ThemeChanged(_), .. } => {
                refresh_theme(&windows, &shared_for_loop);
            }
            _ => {}
        }
    });
}

/// The main window, drawn from the project's `rosezm.app.json` "window"
/// section: the same size, the same immersive chrome and the same SYSTEM
/// material the Electron shell reads from the same file.
fn build_window(event_loop: &EventLoopWindowTarget<NativeEvent>) -> Window {
    let (w, h) = if config::START_ROUTE.is_empty() {
        (config::WIDTH, config::HEIGHT)
    } else {
        (config::START_WIDTH, config::START_HEIGHT)
    };
    let window = base_builder(app_display_name(), w, h, config::START_ROUTE.is_empty())
        .build(event_loop)
        .expect("build the main window");
    // The login window is a fixed-size sheet: no resizing, no maximising.
    if !config::START_ROUTE.is_empty() {
        window.set_resizable(false);
        window.set_maximizable(false);
    }
    if config::ALWAYS_ON_TOP {
        window.set_always_on_top(true);
    }
    window
}

/// The app's name in the user's language: the system's own preference picks
/// the locale, the project's localizations supply the name. The base name is
/// the fallback, so a system language with no entry still gets a name.
fn app_display_name() -> &'static str {
    if config::APP_NAME_LOCALIZATIONS.is_empty() {
        return config::APP_NAME;
    }
    for lang in system_languages() {
        let lang = lang.to_ascii_lowercase();
        // "zh-Hans-CN" matches the "zh-Hans" and "zh" entries; an exact tag
        // wins over the plain language.
        for (tag, name) in config::APP_NAME_LOCALIZATIONS {
            let tag = tag.to_ascii_lowercase();
            if lang == tag {
                return name;
            }
        }
        for (tag, name) in config::APP_NAME_LOCALIZATIONS {
            let tag = tag.to_ascii_lowercase();
            if !tag.contains('-') && lang.starts_with(&format!("{tag}-")) {
                return name;
            }
        }
    }
    config::APP_NAME
}

/// The languages the system asks for, most preferred first.
#[cfg(target_os = "macos")]
fn system_languages() -> Vec<String> {
    use objc2_foundation::NSLocale;
    NSLocale::preferredLanguages()
        .iter()
        .map(|s| s.to_string())
        .collect()
}

#[cfg(not(target_os = "macos"))]
fn system_languages() -> Vec<String> {
    Vec::new()
}

/// A second window (the floating panes the page opens): the same chrome and
/// the same material as the main window, its own size.
fn build_child_window(event_loop: &EventLoopWindowTarget<NativeEvent>, title: &str, width: f64, height: f64, always_on_top: bool) -> Window {
    let window = base_builder(title, width, height, true).build(event_loop).expect("build the child window");
    if always_on_top {
        window.set_always_on_top(true);
    }
    window
}

/// The chrome every window of this app shares: the immersive frame, the
/// traffic lights, the transparent background the material shows through.
fn base_builder(title: &str, width: f64, height: f64, with_min: bool) -> WindowBuilder {
    let mut builder = WindowBuilder::new()
        .with_title(title)
        .with_inner_size(LogicalSize::new(width, height));
    if with_min && config::MIN_WIDTH > 0.0 && config::MIN_HEIGHT > 0.0 {
        builder = builder.with_min_inner_size(LogicalSize::new(config::MIN_WIDTH, config::MIN_HEIGHT));
    } else if !with_min {
        // The login sheet is smaller than the editor's floor: no minimum.
        builder = builder.with_min_inner_size(LogicalSize::new(0.0, 0.0));
    }

    #[cfg(any(target_os = "windows", target_os = "linux"))]
    {
        // Immersive chrome on Windows and Linux: no OS titlebar, the page
        // draws its own (the Windows/Linux traffic lights do not exist).
        if config::FRAMELESS {
            builder = builder.with_decorations(false);
        }
    }

    #[cfg(target_os = "macos")]
    {
        use tao::platform::macos::WindowBuilderExtMacOS;
        match config::TITLE_BAR_STYLE {
            "hiddenInset" => {
                builder = builder
                    .with_titlebar_transparent(true)
                    .with_title_hidden(true)
                    .with_fullsize_content_view(true);
            }
            "hidden" => {
                builder = builder
                    .with_titlebar_transparent(true)
                    .with_title_hidden(true)
                    .with_titlebar_buttons_hidden(true);
            }
            _ => {}
        }
    }

    builder
}

/// The SYSTEM material behind the page: macOS vibrancy (NSVisualEffectView),
/// Windows Mica. Linux has neither - it falls back to the solid background,
/// which is the honest platform behaviour, not a CSS imitation.
fn apply_material(window: &Window) {
    #[cfg(target_os = "macos")]
    {
        if config::VIBRANCY.is_empty() {
            return;
        }
        use window_vibrancy::{apply_vibrancy, NSVisualEffectMaterial, NSVisualEffectState};
        let material = match config::VIBRANCY {
            "sidebar" => NSVisualEffectMaterial::Sidebar,
            "under-window" => NSVisualEffectMaterial::UnderWindowBackground,
            "content" => NSVisualEffectMaterial::ContentBackground,
            "popover" => NSVisualEffectMaterial::Popover,
            "hud" => NSVisualEffectMaterial::HudWindow,
            "fullscreen-ui" => NSVisualEffectMaterial::FullScreenUI,
            "header" => NSVisualEffectMaterial::HeaderView,
            "sheet" => NSVisualEffectMaterial::Sheet,
            "window" => NSVisualEffectMaterial::WindowBackground,
            "titlebar" => NSVisualEffectMaterial::Titlebar,
            "menu" => NSVisualEffectMaterial::Menu,
            "selection" => NSVisualEffectMaterial::Selection,
            "tooltip" => NSVisualEffectMaterial::Tooltip,
            "under-page" => NSVisualEffectMaterial::UnderPageBackground,
            _ => NSVisualEffectMaterial::Sidebar,
        };
        let state = match config::VISUAL_EFFECT_STATE {
            "active" => Some(NSVisualEffectState::Active),
            "inactive" => Some(NSVisualEffectState::Inactive),
            _ => None,
        };
        // The material lives behind the window; a failure here is a missing
        // blur, never a crash.
        unsafe {
            let _ = apply_vibrancy(window, material, state, Some(12.0));
        }
    }
    #[cfg(target_os = "windows")]
    {
        if config::BACKGROUND_MATERIAL.is_empty() || config::BACKGROUND_MATERIAL == "none" {
            return;
        }
        use window_vibrancy::apply_mica;
        unsafe {
            let _ = apply_mica(window, Some(false));
        }
    }
}

/// Centre the window on its monitor - the same "center": true the Electron
/// shell honours.
fn center_window(window: &Window) {
    let Some(monitor) = window.current_monitor() else { return };
    let size = window.outer_size();
    let monitor_size = monitor.size();
    let monitor_pos = monitor.position();
    let x = monitor_pos.x + ((monitor_size.width.saturating_sub(size.width)) / 2) as i32;
    let y = monitor_pos.y + ((monitor_size.height.saturating_sub(size.height)) / 2) as i32;
    window.set_outer_position(tao::dpi::PhysicalPosition::new(x, y));
}

/// A standard-height unified title bar, which is what makes AppKit lay the
/// native traffic lights out at the platform inset instead of cramming them
/// into the collapsed container `fullSizeContentView` leaves behind. An empty
/// NSToolbar is exactly what native macOS apps use; no position is hardcoded.
/// Called before the webview replaces the content view.
#[cfg(target_os = "macos")]
fn apply_system_toolbar(window: &Window) { set_system_toolbar(window, true); }

/// Native fullscreen keeps a Unified toolbar as a 68px opaque white band above
/// the content (the traffic lights have already moved to the menu bar). Drop
/// the toolbar while fullscreen so the webview fills the screen; restore it on
/// exit so AppKit lays the lights out at the platform inset again.
#[cfg(target_os = "macos")]
fn set_system_toolbar(window: &Window, on: bool) {
    use objc2::MainThreadMarker;
    use objc2_app_kit::{NSWindow, NSWindowToolbarStyle, NSToolbar};
    use tao::platform::macos::WindowExtMacOS;
    let raw = window.ns_window();
    if raw.is_null() { return; }
    let win: &NSWindow = unsafe { &*(raw as *const NSWindow) };
    if on {
        let toolbar = NSToolbar::new(unsafe { MainThreadMarker::new_unchecked() });
        toolbar.setShowsBaselineSeparator(false);
        win.setToolbarStyle(NSWindowToolbarStyle::Unified);
        win.setToolbar(Some(&toolbar));
    } else {
        win.setToolbar(None);
    }
}

#[cfg(target_os = "macos")]
fn sync_fullscreen_toolbar(window: &Window, was_full: &mut bool) {
    use objc2_app_kit::{NSWindow, NSWindowStyleMask};
    use tao::platform::macos::WindowExtMacOS;
    let raw = window.ns_window();
    if raw.is_null() { return; }
    let win: &NSWindow = unsafe { &*(raw as *const NSWindow) };
    let full = win.styleMask().contains(NSWindowStyleMask::FullScreen);
    if full == *was_full { return; }
    *was_full = full;
    set_system_toolbar(window, !full);
}

/// A solid plate over the webview while it boots: WKWebView shows its own
/// white until the first document paints, which on a cold start is the blank
/// the user sees. A thin grey layer in the app's own background tone removes
/// the flash without touching the vibrancy underneath (it is removed the
/// moment the page reports it loaded). Returns nothing on non-macOS.
#[cfg(target_os = "macos")]
fn install_boot_cover(window: &Window) -> Option<objc2::rc::Retained<objc2_app_kit::NSView>> {
    use objc2::MainThreadMarker;
    use objc2::AllocAnyThread;
    use objc2_app_kit::{NSColor, NSImage, NSImageView, NSView};
    use objc2_foundation::{NSData, NSPoint, NSSize};
    use tao::platform::macos::WindowExtMacOS;
    let mtm = MainThreadMarker::new()?;
    let raw = window.ns_window();
    if raw.is_null() { return None; }
    let win: &objc2_app_kit::NSWindow = unsafe { &*(raw as *const objc2_app_kit::NSWindow) };
    let content = win.contentView()?;
    let frame = content.frame();
    let cover = NSView::new(mtm);
    cover.setFrame(frame);
    cover.setWantsLayer(true);
    if let Some(layer) = cover.layer() {
        // Match the login sheet's light chrome; light/dark is handled by the
        // window's own appearance, so a mid-grey works for both.
        let color = NSColor::colorWithSRGBRed_green_blue_alpha(0.95, 0.95, 0.96, 1.0);
        layer.setBackgroundColor(Some(&color.CGColor()));
    }
    cover.setAutoresizingMask(
        objc2_app_kit::NSAutoresizingMaskOptions::ViewWidthSizable
            | objc2_app_kit::NSAutoresizingMaskOptions::ViewHeightSizable,
    );

    // The logo. Drawn natively so it shows BEFORE the web bundle is parsed -
    // an in-page splash would still wait behind the 700 KB bundle. The bytes
    // are the same embedded asset the site serves.
    if let Some((_, bytes)) = assets::ASSETS.iter().find(|(p, _)| *p == "public/logo.png") {
        let data = unsafe { NSData::dataWithBytes_length(bytes.as_ptr() as *const std::ffi::c_void, bytes.len()) };
        if let Some(img) = NSImage::initWithData(NSImage::alloc(), &data) {
            let size = 96.0;
            let x = (frame.size.width - size) / 2.0;
            let y = (frame.size.height - size) / 2.0;
            let iv = NSImageView::new(mtm);
            iv.setFrame(objc2_foundation::NSRect::new(NSPoint::new(x, y), NSSize::new(size, size)));
            iv.setImage(Some(&img));
            iv.setImageScaling(objc2_app_kit::NSImageScaling::ScaleProportionallyUpOrDown);
            iv.setWantsLayer(true);
            if let Some(ivl) = iv.layer() {
                // Mac launch-style hop: a few decaying bounces, rendered on the
                // layer's own thread (no timer, no JS - works while the web
                // bundle is still parsing).
                let center = y + size / 2.0;
                let hops = [0.0f64, 30.0, 0.0, 14.0, 0.0, 5.0, 0.0];
                let times = [0.0f64, 0.18, 0.36, 0.52, 0.68, 0.84, 1.0];
                let values: Vec<objc2::rc::Retained<objc2::runtime::AnyObject>> = hops
                    .iter()
                    .map(|h| unsafe { objc2::rc::Retained::cast_unchecked(objc2_foundation::NSNumber::new_f64(center + h)) })
                    .collect();
                let key_times: Vec<objc2::rc::Retained<objc2_foundation::NSNumber>> =
                    times.iter().map(|t| objc2_foundation::NSNumber::new_f64(*t)).collect();
                let tf = objc2_quartz_core::CAMediaTimingFunction::functionWithName(
                    unsafe { objc2_quartz_core::kCAMediaTimingFunctionEaseOut },
                );
                let tfs: Vec<objc2::rc::Retained<objc2_quartz_core::CAMediaTimingFunction>> =
                    (0..times.len()).map(|_| tf.clone()).collect();
                use objc2_quartz_core::CAMediaTiming;
                let anim = objc2_quartz_core::CAKeyframeAnimation::new();
                anim.setKeyPath(Some(&objc2_foundation::NSString::from_str("position.y")));
                unsafe { anim.setValues(Some(&objc2_foundation::NSArray::from_retained_slice(&values))) };
                anim.setKeyTimes(Some(&objc2_foundation::NSArray::from_retained_slice(&key_times)));
                anim.setTimingFunctions(Some(&objc2_foundation::NSArray::from_retained_slice(&tfs)));
                anim.setDuration(1.15);
                anim.setRepeatCount(f32::INFINITY);
                ivl.addAnimation_forKey(&anim, Some(&objc2_foundation::NSString::from_str("bootbounce")));
            }
            cover.addSubview(&iv);
        }
    }

    content.addSubview(&cover);
    Some(cover)
}


#[cfg(not(target_os = "macos"))]
fn install_boot_cover(_window: &Window) -> Option<()> { None }

#[cfg(not(target_os = "macos"))]
fn apply_system_toolbar(_window: &Window) {}
#[cfg(not(target_os = "macos"))]
fn sync_fullscreen_toolbar(_window: &Window, _was_full: &mut bool) {}

/// The WebView, drawing the baked site. The background follows the project's
/// background color: under a material the page must paint its own alpha, so
/// the webview background is transparent.
fn build_webview(window: &Window, port: u16, route: &str, on_loaded: Option<Box<dyn Fn() + 'static>>) -> wry::WebView {
    apply_system_toolbar(window);
    let origin = format!("http://127.0.0.1:{port}");
    let url = format!("{origin}{route}");
    let mut builder = WebViewBuilder::new()
        .with_url(url)
        .with_transparent(true)
        .with_on_page_load_handler(move |event, _url| {
            if let wry::PageLoadEvent::Finished = event {
                if let Some(cb) = on_loaded.as_ref() { cb(); }
            }
        })
        // The app owns its own origin: a link to somewhere else goes to the
        // system browser instead of navigating the app's window away.
        .with_navigation_handler(move |target| {
            if target.starts_with(&origin) || target.starts_with("about:") || target.starts_with("data:") || target.starts_with("blob:") {
                return true;
            }
            open_external(&target);
            false
        });
    let color = config::BACKGROUND_COLOR;
    if let Some(rgba) = parse_rgba(color) {
        builder = builder.with_background_color(rgba);
    }
    builder.build(window).expect("build the webview")
}

/// Hand a URL to the system browser - the same job the Electron shell's
/// openExternal does.
fn open_external(url: &str) {
    if !(url.starts_with("http://") || url.starts_with("https://") || url.starts_with("mailto:") || url.starts_with("tel:")) {
        return;
    }
    #[cfg(target_os = "macos")]
    let _ = std::process::Command::new("open").arg(url).spawn();
    #[cfg(target_os = "linux")]
    let _ = std::process::Command::new("xdg-open").arg(url).spawn();
    #[cfg(target_os = "windows")]
    let _ = std::process::Command::new("cmd").args(["/C", "start", "", url]).spawn();
}

/// '#RRGGBB' or '#RRGGBBAA' -> the RGBA the webview paints behind the page.
fn parse_rgba(color: &str) -> Option<wry::RGBA> {
    let hex = color.trim().trim_start_matches('#');
    if hex.len() != 6 && hex.len() != 8 {
        return None;
    }
    let byte = |i: usize| u8::from_str_radix(&hex[i..i + 2], 16).ok();
    let r = byte(0)?;
    let g = byte(2)?;
    let b = byte(4)?;
    let a = if hex.len() == 8 { byte(6)? } else { 0xff };
    Some((r, g, b, a))
}

/// The window tells the page which window it is, so a message can skip its
/// own sender the way the Electron shell does.
fn set_window_id(webview: &wry::WebView, id: u64) {
    let _ = webview.evaluate_script(&format!("window.__rosezmWindowId = {id};"));
}

/// The OS appearance, as a number the request threads can read without
/// touching the window.
fn refresh_theme(windows: &[WindowRec], shared: &Shared) {
    if let Some(rec) = windows.first() {
        shared.set_dark(rec.window.theme() == tao::window::Theme::Dark);
    }
}

/// ---------------------------------------------------------------- native

/// Answer one capability request. The request arrives as JSON
/// `{"capability": "...", "options": {...}}` and the answer is the same JSON
/// the capability contract promises: the value, or null.
fn native_call(body: &str, shared: &Shared, proxy: &EventLoopProxy<NativeEvent>) -> Value {
    let request: Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => return Value::Null,
    };
    let capability = request.get("capability").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let options = request.get("options").cloned().unwrap_or(Value::Null);
    let from = request.get("window").and_then(|v| v.as_u64()).unwrap_or(0);

    match capability.as_str() {
        // The OS appearance, and the platform the shell runs on.
        "get-system-info" => json!({ "platform": platform_name(), "dark": shared.is_dark() }),
        // The app's own identity, plus the arguments it was started with (the
        // workspace the user opened on the command line).
        "app-info" => json!({
            "id": config::APP_ID,
            "name": app_display_name(),
            "version": config::APP_VERSION,
            "build": config::APP_BUILD,
            "argv": std::env::args().skip(1).collect::<Vec<String>>(),
        }),
        // Where AppKit actually put the traffic lights: measured on the main
        // thread from the native buttons, never a hardcoded pixel.
        "window-traffic-lights" => ask(proxy, |reply| NativeEvent::TrafficLights { from, reply })
            .unwrap_or(Value::Null),
        "set-theme-source" => {
            let source = options.get("source").and_then(|v| v.as_str()).unwrap_or("").to_string();
            if source != "system" && source != "light" && source != "dark" {
                return json!({ "ok": false });
            }
            ask(proxy, |reply| NativeEvent::Theme { source, reply })
                .unwrap_or_else(|| json!({ "ok": false }))
        }
        "window-control" => {
            let action = options.get("action").and_then(|v| v.as_str()).unwrap_or("").to_string();
            ask(proxy, |reply| NativeEvent::WindowControl { action, from, reply }).unwrap_or(Value::Null)
        }
        // Frameless window drag: WKWebView does not honour Electron's
        // -webkit-app-region, so the page asks the shell to start the native
        // drag from its mousedown on an empty chrome area.
        "window-drag" => ask(proxy, |reply| NativeEvent::WindowControl { action: "drag".into(), from, reply })
            .unwrap_or(Value::Null),
        "window-open" => {
            let route = options.get("route").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let title = options.get("title").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let width = options.get("width").and_then(|v| v.as_f64()).unwrap_or(440.0);
            let height = options.get("height").and_then(|v| v.as_f64()).unwrap_or(640.0);
            let always_on_top = options.get("alwaysOnTop").and_then(|v| v.as_bool()).unwrap_or(false);
            ask(proxy, |reply| NativeEvent::OpenWindow {
                route,
                title,
                width,
                height,
                always_on_top,
                reply,
            })
            .unwrap_or(Value::Null)
        }
        "window-swap" => ask(proxy, |reply| NativeEvent::SwapWindow { from, reply }).unwrap_or(Value::Null),
        "window-resize" => {
            let width = options.get("width").and_then(|v| v.as_f64()).unwrap_or(0.0);
            let height = options.get("height").and_then(|v| v.as_f64()).unwrap_or(0.0);
            let resizable = options.get("resizable").and_then(|v| v.as_bool()).unwrap_or(false);
            ask(proxy, |reply| NativeEvent::ResizeWindow { from, width, height, resizable, reply }).unwrap_or(Value::Null)
        }
        "window-post" => {
            let channel = options.get("channel").and_then(|v| v.as_str()).unwrap_or("").to_string();
            if channel.is_empty() {
                return Value::Bool(false);
            }
            let payload = options.get("payload").cloned().unwrap_or(Value::Null);
            let data = json!({
                "channel": channel,
                "payload": payload,
                "from": from,
                "at": now_ms(),
            });
            ask(proxy, |reply| NativeEvent::Post { data, from, reply })
                .map(Value::Bool)
                .unwrap_or(Value::Bool(false))
        }
        "context-menu" => {
            let items = options.get("items").and_then(|v| v.as_array()).cloned().unwrap_or_default();
            let x = options.get("x").and_then(|v| v.as_f64());
            let y = options.get("y").and_then(|v| v.as_f64());
            ask(proxy, |reply| NativeEvent::ContextMenu { items, x, y, reply })
                .map(|answer| match answer {
                    Some(id) => Value::String(id),
                    None => Value::Null,
                })
                .unwrap_or(Value::Null)
        }
        "modal" => {
            let title = options.get("title").and_then(|v| v.as_str()).unwrap_or(app_display_name()).to_string();
            let message = options.get("message").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let buttons = options
                .get("buttons")
                .and_then(|v| v.as_array())
                .map(|a| a.iter().filter_map(|b| b.as_str().map(|s| s.to_string())).take(6).collect::<Vec<String>>())
                .filter(|b: &Vec<String>| !b.is_empty())
                .unwrap_or_else(|| vec!["OK".to_string(), "Cancel".to_string()]);
            ask(proxy, |reply| NativeEvent::Modal { title, message, buttons, reply })
                .map(Value::Bool)
                .unwrap_or(Value::Bool(false))
        }
        "notify" => {
            let title = options.get("title").and_then(|v| v.as_str()).unwrap_or(app_display_name()).to_string();
            let body = options.get("body").and_then(|v| v.as_str()).unwrap_or("").to_string();
            ask(proxy, |reply| NativeEvent::Notify { title, body, reply })
                .map(Value::Bool)
                .unwrap_or(Value::Bool(false))
        }
        "set-window-title" => {
            let title = options.get("title").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let from = options.get("from").and_then(|v| v.as_u64()).unwrap_or(1);
            ask(proxy, |reply| NativeEvent::SetWindowTitle { from, title, reply })
                .map(Value::Bool)
                .unwrap_or(Value::Bool(false))
        }
        "clipboard-read" => {
            ask(proxy, |reply| NativeEvent::ClipboardRead { reply })
                .map(|answer| match answer {
                    Some(text) => Value::String(text),
                    None => Value::Null,
                })
                .unwrap_or(Value::Null)
        }
        "clipboard-write" => {
            let text = options.get("text").and_then(|v| v.as_str()).unwrap_or("").to_string();
            ask(proxy, |reply| NativeEvent::ClipboardWrite { text, reply })
                .map(Value::Bool)
                .unwrap_or(Value::Bool(false))
        }
        // The workspace file system. The renderer is sandboxed, so the shell
        // answers: scoped to the folder the user picked and the exact files
        // they chose, never the whole disk.
        "fs-authorize-root" => {
            let path = options.get("path").and_then(|v| v.as_str()).unwrap_or("");
            authorize_root(shared, path)
        }
        "fs-pick-directory" => {
            let title = options.get("title").and_then(|v| v.as_str()).unwrap_or("Open workspace").to_string();
            match ask(proxy, |reply| NativeEvent::PickDirectory { title, reply }) {
                Some(Some(paths)) => {
                    // The picked folder becomes the workspace root.
                    if let Some(first) = paths.first() {
                        set_root(shared, Path::new(first));
                    }
                    json!(paths)
                }
                _ => Value::Null,
            }
        }
        "fs-pick-file" => {
            let title = options.get("title").and_then(|v| v.as_str()).unwrap_or("Open file").to_string();
            let multi = options.get("multi").and_then(|v| v.as_bool()).unwrap_or(false);
            let filters = options
                .get("filters")
                .and_then(|v| v.as_array())
                .map(|a| {
                    a.iter()
                        .filter_map(|f| {
                            let name = f.get("name").and_then(|v| v.as_str()).unwrap_or("Files").to_string();
                            let extensions = f
                                .get("extensions")
                                .and_then(|v| v.as_array())
                                .map(|e| e.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).take(32).collect::<Vec<String>>())
                                .unwrap_or_else(|| vec!["*".to_string()]);
                            Some((name, extensions))
                        })
                        .take(12)
                        .collect::<Vec<(String, Vec<String>)>>()
                })
                .unwrap_or_default();
            match ask(proxy, |reply| NativeEvent::PickFile { title, multi, filters, reply }) {
                Some(Some(paths)) => {
                    // A picked file is readable - itself, never its neighbours.
                    if let Ok(mut picked) = shared.picked.lock() {
                        for p in &paths {
                            picked.push(PathBuf::from(p));
                        }
                    }
                    json!(paths)
                }
                _ => Value::Null,
            }
        }
        "fs-list" => {
            let dir = options.get("dir").and_then(|v| v.as_str()).unwrap_or("");
            match inside(shared, dir) {
                Some(path) => fs_list(&path),
                None => Value::Null,
            }
        }
        "fs-read" => {
            let path = options.get("path").and_then(|v| v.as_str()).unwrap_or("");
            match inside(shared, path) {
                Some(path) => match std::fs::read_to_string(&path) {
                    Ok(text) => Value::String(text),
                    Err(_) => Value::Null,
                },
                None => Value::Null,
            }
        }
        "fs-write" => {
            let path = options.get("path").and_then(|v| v.as_str()).unwrap_or("");
            let content = options.get("content").and_then(|v| v.as_str()).unwrap_or("");
            match inside(shared, path) {
                Some(path) => {
                    if let Some(parent) = path.parent() {
                        let _ = std::fs::create_dir_all(parent);
                    }
                    let nonce = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|d| d.as_nanos())
                        .unwrap_or(0);
                    let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("file");
                    let tmp = path.with_file_name(format!(".{}.{}.dvtmp", name, nonce));
                    let ok = if std::fs::write(&tmp, content).is_ok() {
                        if let Ok(meta) = std::fs::metadata(&path) {
                            let _ = std::fs::set_permissions(&tmp, meta.permissions());
                        }
                        std::fs::rename(&tmp, &path).is_ok()
                    } else { false };
                    if !ok { let _ = std::fs::remove_file(&tmp); }
                    Value::Bool(ok)
                }
                None => Value::Bool(false),
            }
        }
        "fs-mkdir" => {
            let path = options.get("path").and_then(|v| v.as_str()).unwrap_or("");
            match inside(shared, path) {
                Some(path) => Value::Bool(std::fs::create_dir_all(&path).is_ok()),
                None => Value::Bool(false),
            }
        }
        "fs-rename" => {
            let from = options.get("from").and_then(|v| v.as_str()).unwrap_or("");
            let to = options.get("to").and_then(|v| v.as_str()).unwrap_or("");
            let (Some(from), Some(to)) = (inside(shared, from), inside(shared, to)) else {
                return Value::Bool(false);
            };
            // The root itself is not a file: renaming it would move the
            // workspace out from under the app.
            if is_root(shared, &from) {
                return Value::Bool(false);
            }
            if to.exists() { return Value::Bool(false); }
            Value::Bool(std::fs::rename(&from, &to).is_ok())
        }
        "fs-remove" => {
            let path = options.get("path").and_then(|v| v.as_str()).unwrap_or("");
            let Some(target) = inside(shared, path) else { return Value::Bool(false) };
            if is_root(shared, &target) {
                return Value::Bool(false);
            }
            let removed = if target.is_dir() {
                std::fs::remove_dir_all(&target).is_ok()
            } else {
                std::fs::remove_file(&target).is_ok()
            };
            Value::Bool(removed)
        }
        // A link the app opens in the system browser.
        "open-external" => {
            let url = options.get("url").and_then(|v| v.as_str()).unwrap_or("");
            open_external(url);
            Value::Bool(true)
        }
        // Every other capability is unknown to this shell: the contract's
        // empty answer, never a throw inside a tap handler.
        _ => Value::Null,
    }
}

/// Send one request to the event loop and wait for its answer.
fn ask<T>(proxy: &EventLoopProxy<NativeEvent>, make: impl FnOnce(Sender<T>) -> NativeEvent) -> Option<T> {
    let (tx, rx) = channel();
    if proxy.send_event(make(tx)).is_err() {
        return None;
    }
    rx.recv().ok()
}

fn platform_name() -> &'static str {
    if cfg!(target_os = "macos") {
        "mac"
    } else if cfg!(target_os = "windows") {
        "win"
    } else if cfg!(target_os = "linux") {
        "linux"
    } else {
        "web"
    }
}

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

// -------------------------------------------------------------- filesystem

/// The folder the user opened becomes the workspace root: the same trust
/// the picker asks for, without a dialog. It must be an existing directory.
fn authorize_root(shared: &Shared, path: &str) -> Value {
    let target = Path::new(path);
    if !target.is_dir() {
        return Value::Bool(false);
    }
    let Ok(resolved) = target.canonicalize() else { return Value::Bool(false) };
    set_root(shared, &resolved);
    Value::Bool(true)
}

fn set_root(shared: &Shared, path: &Path) {
    if let Ok(mut root) = shared.root.lock() {
        *root = Some(path.to_path_buf());
    }
    if let Ok(mut picked) = shared.picked.lock() {
        picked.clear();
    }
}

fn is_root(shared: &Shared, path: &Path) -> bool {
    shared
        .root
        .lock()
        .ok()
        .and_then(|root| root.as_ref().map(|r| r == path))
        .unwrap_or(false)
}

/// The path the shell is allowed to touch: inside the workspace root, or a
/// file the user picked. A resolved path with a boundary check - never a
/// prefix test, which would accept a sibling directory.
fn inside(shared: &Shared, path: &str) -> Option<PathBuf> {
    if path.is_empty() {
        return None;
    }
    let raw = Path::new(path);
    let resolved = if raw.exists() {
        raw.canonicalize().ok()?
    } else {
        // A file that does not exist yet: its parent has to.
        let parent = raw.parent()?;
        let name = raw.file_name()?;
        parent.canonicalize().ok()?.join(name)
    };
    if let Ok(root) = shared.root.lock() {
        if let Some(root) = root.as_ref() {
            if resolved == *root || resolved.starts_with(root) {
                return Some(resolved);
            }
            return None;
        }
    }
    // No root: only the files the user picked themselves.
    if let Ok(picked) = shared.picked.lock() {
        if picked.iter().any(|p| *p == resolved) {
            return Some(resolved);
        }
    }
    None
}

/// One directory listing, the shape the file shim expects.
fn fs_list(dir: &Path) -> Value {
    let Ok(entries) = std::fs::read_dir(dir) else { return Value::Null };
    let mut out: Vec<Value> = Vec::new();
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        let path = entry.path();
        let mut is_dir = entry.file_type().map(|t| t.is_dir()).unwrap_or(false);
        let mut size = 0u64;
        let mut mtime = 0u64;
        if let Ok(meta) = std::fs::metadata(&path) {
            is_dir = meta.is_dir();
            size = meta.len();
            mtime = meta
                .modified()
                .ok()
                .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
                .map(|d| d.as_millis() as u64)
                .unwrap_or(0);
        }
        out.push(json!({
            "name": name,
            "path": path.to_string_lossy(),
            "isDir": is_dir,
            "size": size,
            "mtime": mtime,
        }));
    }
    Value::Array(out)
}

// ------------------------------------------------------------ event loop

/// Do what the page asked, on the thread that owns the window.
fn handle_native(event: NativeEvent, elwt: &EventLoopWindowTarget<NativeEvent>, port: u16, windows: &mut Vec<WindowRec>, shared: &Shared) {
    match event {
        NativeEvent::WindowControl { action, from, reply } => {
            let rec = windows.iter().find(|w| w.id == from).or_else(|| windows.first()).map(|r| &r.window);
            let Some(window) = rec else { return };
            match action.as_str() {
                "minimize" => window.set_minimized(true),
                "maximize" => window.set_maximized(true),
                "unmaximize" => window.set_maximized(false),
                "toggle-maximize" => window.set_maximized(!window.is_maximized()),
                "fullscreen" => {
                    let on = window.fullscreen().is_some();
                    window.set_fullscreen(if on { None } else { Some(tao::window::Fullscreen::Borderless(None)) });
                }
                "always-on-top" => window.set_always_on_top(!window.is_always_on_top()),
                "hide" => window.set_visible(false),
                "show" => window.set_visible(true),
                "focus" => window.set_focus(),
                // The native drag loop takes over until the mouse is released.
                "drag" => {
                    let _ = window.drag_window();
                    return;
                }
                "close" => {
                    let _ = reply.send(json!({ "closing": true }));
                    return;
                }
                _ => {}
            }
            // The live state, so the maximize glyph never lies.
            let _ = reply.send(json!({
                "maximized": window.is_maximized(),
                "fullscreen": window.fullscreen().is_some(),
                "alwaysOnTop": window.is_always_on_top(),
                "visible": window.is_visible(),
            }));
        }
        NativeEvent::Theme { source, reply } => {
            let Some(rec) = windows.first() else { return };
            let theme = match source.as_str() {
                "dark" => Some(tao::window::Theme::Dark),
                "light" => Some(tao::window::Theme::Light),
                _ => None,
            };
            rec.window.set_theme(theme);
            let dark = rec.window.theme() == tao::window::Theme::Dark;
            shared.set_dark(dark);
            let _ = reply.send(json!({ "ok": true, "dark": dark }));
        }
        NativeEvent::SwapWindow { from, reply } => {
            // Already swapped (double click / stale page): just focus the editor.
            if let Some(rec) = windows.iter().find(|w| w.route == "/") {
                rec.window.set_focus();
                let _ = reply.send(json!({ "ok": true }));
                return;
            }
            let child = build_child_window(elwt, &app_display_name(), config::WIDTH, config::HEIGHT, false);
            let webview = build_webview(&child, port, "/", None);
            apply_material(&child);
            let id = windows.iter().map(|w| w.id).max().unwrap_or(1) + 1;
            set_window_id(&webview, id);
            windows.push(WindowRec { id, route: "/".to_string(), window: child, webview });
            // Drop the login window: dropping its Window closes it. Keep at
            // least one window alive so the event loop does not exit.
            if windows.len() > 1 {
                windows.retain(|w| w.id != from);
            }
            let _ = reply.send(json!({ "ok": true }));
        }
        NativeEvent::ResizeWindow { from, width, height, resizable, reply } => {
            let Some(rec) = windows.iter().find(|w| w.id == from) else {
                let _ = reply.send(json!({ "ok": false }));
                return;
            };
            rec.window.set_resizable(resizable);
            if width > 0.0 && height > 0.0 {
                // The window must shrink to the requested size, not be held
                // back by the frame's minimum: the login sheet is narrow.
                rec.window.set_min_inner_size(Some(tao::dpi::LogicalSize::new(0.0, 0.0)));
                rec.window.set_inner_size(tao::dpi::LogicalSize::new(width, height));
            }
            let _ = reply.send(json!({ "ok": true }));
        }
        NativeEvent::OpenWindow { route, title, width, height, always_on_top, reply } => {
            // An already-open route is focused instead: a double click never
            // stacks twins.
            if let Some(rec) = windows.iter().find(|w| w.route == route) {
                rec.window.set_focus();
                let _ = reply.send(json!({ "ok": true, "opened": false, "route": route }));
                return;
            }
            let child = build_child_window(elwt, &title, width, height, always_on_top);
            let webview = build_webview(&child, port, &route, None);
            apply_material(&child);
            let id = windows.iter().map(|w| w.id).max().unwrap_or(1) + 1;
            set_window_id(&webview, id);
            windows.push(WindowRec { id, route: route.clone(), window: child, webview });
            let _ = reply.send(json!({ "ok": true, "opened": true, "route": route }));
        }
        NativeEvent::Post { data, from, reply } => {
            let script = format!(
                "window.dispatchEvent(new CustomEvent('rosezm:window-event', {{ detail: {data} }}));"
            );
            let mut sent = false;
            for rec in windows.iter() {
                if rec.id == from {
                    continue;
                }
                if rec.webview.evaluate_script(&script).is_ok() {
                    sent = true;
                }
            }
            let _ = reply.send(sent);
        }
        NativeEvent::ContextMenu { items, x, y, reply } => {
            let answer = show_context_menu(windows.first(), &items, x, y);
            let _ = reply.send(answer);
        }
        NativeEvent::PickDirectory { title, reply } => {
            let answer = rfd::FileDialog::new()
                .set_title(&title)
                .pick_folder()
                .map(|p| vec![p.to_string_lossy().to_string()]);
            let _ = reply.send(answer);
        }
        NativeEvent::PickFile { title, multi, filters, reply } => {
            let mut dialog = rfd::FileDialog::new().set_title(&title);
            for (name, extensions) in filters {
                let exts: Vec<&str> = extensions
                    .iter()
                    .map(|e| e.trim_start_matches('.'))
                    .filter(|e| *e != "*" && !e.is_empty())
                    .collect();
                if !exts.is_empty() {
                    dialog = dialog.add_filter(&name, &exts);
                }
            }
            let picked = if multi { dialog.pick_files() } else { dialog.pick_file().map(|p| vec![p]) };
            let answer = picked.map(|paths| paths.iter().map(|p| p.to_string_lossy().to_string()).collect::<Vec<String>>());
            let _ = reply.send(answer);
        }
        NativeEvent::Modal { title, message, buttons, reply } => {
            let first = buttons.first().cloned().unwrap_or_else(|| "OK".to_string());
            let kind = if buttons.len() < 2 {
                rfd::MessageButtons::OkCustom(first)
            } else {
                rfd::MessageButtons::OkCancelCustom(first, buttons[1].clone())
            };
            let dialog = rfd::MessageDialog::new()
                .set_title(&title)
                .set_description(&message)
                .set_buttons(kind);
            let answer = matches!(dialog.show(), rfd::MessageDialogResult::Yes);
            let _ = reply.send(answer);
        }
        NativeEvent::ClipboardRead { reply } => {
            let answer = arboard::Clipboard::new().ok().and_then(|mut c| c.get_text().ok());
            let _ = reply.send(answer);
        }
        NativeEvent::ClipboardWrite { text, reply } => {
            let answer = arboard::Clipboard::new()
                .and_then(|mut c| c.set_text(text))
                .is_ok();
            let _ = reply.send(answer);
        }
        NativeEvent::Notify { title, body, reply } => {
            let answer = notify_rust::Notification::new()
                .summary(&title)
                .body(&body)
                .show()
                .is_ok();
            let _ = reply.send(answer);
        }
        NativeEvent::SetWindowTitle { from, title, reply } => {
            let rec = windows.iter().find(|w| w.id == from).or_else(|| windows.first());
            if let Some(r) = rec { r.window.set_title(&title); }
            let _ = reply.send(true);
        }
        NativeEvent::TrafficLights { from, reply } => {
            let rec = windows.iter().find(|w| w.id == from).or_else(|| windows.first());
            let value = rec.and_then(|r| native_traffic_light_inset(&r.window)).unwrap_or(Value::Null);
            let _ = reply.send(value);
        }
    }
}

/// Where AppKit actually laid out the native traffic lights, in logical
/// points from the content view's top-left. Measured on the main thread;
/// DPI, macOS version and title bar style are the system's own decision.
#[cfg(target_os = "macos")]
fn native_traffic_light_inset(window: &Window) -> Option<Value> {
    use objc2_app_kit::{NSWindow, NSWindowButton};
    use tao::platform::macos::WindowExtMacOS;

    let raw = window.ns_window();
    if raw.is_null() {
        return None;
    }
    // tao hands back the NSWindow it owns; objc2-app-kit 0.3 is the same
    // version tao itself uses, so this is that very object, not a copy.
    let win: &NSWindow = unsafe { &*(raw as *const NSWindow) };
    let content = win.contentView()?;
    let close = win.standardWindowButton(NSWindowButton::CloseButton)?;
    // bounds is in the button's own coordinate space, which is what
    // convertRect:toView: expects; frame would be in its superview's.
    let rect = close.convertRect_toView(close.bounds(), Some(&content));
    let y = if content.isFlipped() {
        rect.origin.y
    } else {
        content.frame().size.height - rect.origin.y - rect.size.height
    };
    Some(json!({ "x": rect.origin.x.round() as i32, "y": y.round() as i32 }))
}

#[cfg(not(target_os = "macos"))]
fn native_traffic_light_inset(_window: &Window) -> Option<Value> {
    None
}

/// The OS context menu: the items the page describes, popped by the system,
/// answered with the id that was clicked. No DOM imitation.
#[cfg(any(target_os = "macos", target_os = "windows"))]
fn show_context_menu(rec: Option<&WindowRec>, items: &[Value], x: Option<f64>, y: Option<f64>) -> Option<String> {
    use muda::{ContextMenu, Menu, PredefinedMenuItem};

    let mut menu = Menu::new();
    let mut ids: Vec<String> = Vec::new();
    for item in items.iter().take(100) {
        if item.get("separator").and_then(|v| v.as_bool()).unwrap_or(false) {
            let _ = menu.append(&PredefinedMenuItem::separator());
            continue;
        }
        let label = item.get("label").and_then(|v| v.as_str()).unwrap_or("");
        if label.is_empty() {
            continue;
        }
        let label: String = label.chars().take(120).collect();
        let id: String = item
            .get("id")
            .and_then(|v| v.as_str())
            .unwrap_or(label.as_str())
            .chars()
            .take(64)
            .collect();
        let enabled = !item.get("disabled").and_then(|v| v.as_bool()).unwrap_or(false);
        let checked = item.get("checked").and_then(|v| v.as_bool()).unwrap_or(false);
        // The id is the page's own id: the menu event carries it back, so
        // the answer is the id the page named - not muda's internal one.
        if checked {
            let item = muda::CheckMenuItemBuilder::new()
                .id(muda::MenuId::new(id.clone()))
                .text(label)
                .enabled(enabled)
                .checked(checked)
                .build();
            let _ = menu.append(&item);
        } else {
            let item = muda::MenuItemBuilder::new()
                .id(muda::MenuId::new(id.clone()))
                .text(label)
                .enabled(enabled)
                .build();
            let _ = menu.append(&item);
        }
        ids.push(id);
    }
    if ids.is_empty() {
        return None;
    }
    let Some(rec) = rec else { return None };

    #[cfg(target_os = "macos")]
    {
        use tao::platform::macos::WindowExtMacOS;
        // muda's dpi::Position is an enum (physical or logical), not a
        // struct - the physical variant carries the pixel coordinates.
        let position = muda::dpi::Position::Physical(muda::dpi::PhysicalPosition::new(
            x.unwrap_or(0.0) as i32,
            y.unwrap_or(0.0) as i32,
        ));
        unsafe {
            let _ = menu.show_context_menu_for_nsview(rec.window.ns_view(), Some(position));
        }
    }
    #[cfg(target_os = "windows")]
    {
        use tao::platform::windows::WindowExtWindows;
        // muda's dpi::Position is an enum (physical or logical), not a
        // struct - the physical variant carries the pixel coordinates.
        let position = muda::dpi::Position::Physical(muda::dpi::PhysicalPosition::new(
            x.unwrap_or(0.0) as i32,
            y.unwrap_or(0.0) as i32,
        ));
        unsafe {
            let _ = menu.show_context_menu_for_hwnd(rec.window.hwnd(), Some(position));
        }
    }

    // The system menu answers on its own thread; the clicked item arrives as
    // a menu event.
    let receiver = muda::MenuEvent::receiver();
    loop {
        match receiver.recv() {
            Ok(event) => {
                let id = event.id();
                for known in &ids {
                    if *id == muda::MenuId::new(known.clone()) {
                        return Some(known.clone());
                    }
                }
            }
            Err(_) => return None,
        }
    }
}

/// Linux has no menu backend in this shell: the contract's empty answer.
#[cfg(not(any(target_os = "macos", target_os = "windows")))]
fn show_context_menu(_rec: Option<&WindowRec>, _items: &[Value], _x: Option<f64>, _y: Option<f64>) -> Option<String> {
    None
}

// ------------------------------------------------------------------ server

/// One request: the static site, the kernel or the capability bridge.
fn serve(
    mut stream: TcpStream,
    index: &HashMap<&'static str, &'static [u8]>,
    shared: &Shared,
    proxy: &EventLoopProxy<NativeEvent>,
    _port: u16,
) -> std::io::Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut line = String::new();
    if reader.read_line(&mut line)? == 0 {
        return Ok(());
    }
    let mut parts = line.split_whitespace();
    let method = parts.next().unwrap_or("GET").to_string();
    let target = parts.next().unwrap_or("/").to_string();
    let path = target.split('?').next().unwrap_or("/").to_string();
    let mut content_length = 0usize;
    loop {
        let mut header = String::new();
        if reader.read_line(&mut header)? == 0 {
            break;
        }
        if header.trim().is_empty() {
            break;
        }
        if let Some(v) = header.strip_prefix("Content-Length:") {
            content_length = v.trim().parse().unwrap_or(0);
        }
    }

    // Same-origin reverse proxy for the online half. The page's fetch('/api/db')
    // is served here and forwarded to the upstream WITHOUT an Origin header;
    // a direct cross-site fetch from WKWebView is refused by /api/db's
    // Origin===Host check. curl is the platform HTTP client (no new crate).
    if path.starts_with("/api/") {
        let mut body = vec![0u8; content_length];
        reader.read_exact(&mut body)?;
        let (status, mime, reply) = proxy_api(&method, &target, &body);
        return respond_status(&mut stream, status, &mime, &reply);
    }

    if method == "POST" && path == "/kernel/call" {
        let mut body = vec![0u8; content_length];
        reader.read_exact(&mut body)?;
        let parsed: Value = serde_json::from_slice(&body).unwrap_or(Value::Null);
        let m = parsed.get("method").and_then(|m| m.as_str()).unwrap_or("");
        let args = parsed.get("args").map(|a| a.to_string()).unwrap_or_else(|| "[]".into());
        let reply = kernel_call(m, &args);
        return respond(&mut stream, "application/json", reply.as_bytes());
    }

    if method == "POST" && path == "/native/call" {
        let mut body = vec![0u8; content_length];
        reader.read_exact(&mut body)?;
        let text = String::from_utf8_lossy(&body).to_string();
        let value = native_call(&text, shared, proxy);
        let reply = json!({ "v": value }).to_string();
        return respond(&mut stream, "application/json", reply.as_bytes());
    }

    // The baked site. A deep route (/ai) has its own document; a miss falls
    // back to the home document, never a 404 inside the window.
    let clean = path.trim_start_matches('/');
    let lookup = if clean.is_empty() { "index.html".to_string() } else { clean.to_string() };
    // A route like /login resolves to login/index.html. The MIME must follow
    // the key actually served, not the extension-less lookup: WKWebView
    // refuses to render an HTML document sent as application/octet-stream.
    let nested = format!("{lookup}/index.html");
    let flat = format!("{lookup}.html");
    let (key, body) = if let Some(b) = index.get(lookup.as_str()) {
        (lookup.as_str(), b)
    } else if let Some(b) = index.get(nested.as_str()) {
        (nested.as_str(), b)
    } else if let Some(b) = index.get(flat.as_str()) {
        (flat.as_str(), b)
    } else if let Some(b) = index.get("index.html") {
        ("index.html", b)
    } else {
        stream.write_all(b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n")?;
        return Ok(());
    };
    respond(&mut stream, mime_of(key), body)
}

/// The business half: the translated kernel, in-process. It is a CARGO
/// FEATURE, not a hard dependency: a shell whose kernel does not compile yet
/// still builds and runs (`--no-default-features`), and the kernel's absence
/// is an honest answer, never a crash.
#[cfg(feature = "kernel")]
fn kernel_call(method: &str, args: &str) -> String {
    dodovim_kernel::kernel_call(method, args)
}

/// A build without the kernel: the route answers the contract's empty answer.
#[cfg(not(feature = "kernel"))]
fn kernel_call(method: &str, _args: &str) -> String {
    format!("{{\"__error\":\"this build has no kernel (--no-default-features): {method}\"}}")
}

/// Forward /api/* to the upstream. GET has no body; POST relays the exact
/// JSON bytes. `target` keeps the query string. Only /api/ paths are allowed.
fn proxy_api(method: &str, target: &str, body: &[u8]) -> (u16, String, Vec<u8>) {
    let err = |msg: &str| (200u16, "application/json".to_string(), json!({ "data": null, "error": msg }).to_string().into_bytes());
    if target == "/api/dav-proxy" { return proxy_dav(body); }
    let base = config::API_BASE.trim_end_matches('/');
    if base.is_empty() { return err("在线服务未配置（导出时未指定 --api）"); }
    if !target.starts_with("/api/") { return err("invalid api path"); }
    let url = format!("{base}{target}");
    // WebDAV providers branch on the REMOTE status (MOVE 201/204, GET 404 ->
    // null, PROPFIND 207). curl's -w trailer carries the upstream status and
    // content-type through so the page sees the same Response it would on the
    // deployed server; a blanket 200 silently breaks rename and file probes.
    let mut cmd = Command::new("curl");
    cmd.args(["-sS", "--max-time", "15", "-X", method, "-H", "Content-Type: application/json",
              "-w", "\n__DV_META__%{http_code}|%{content_type}"]);
    if method == "POST" || method == "PUT" || method == "PATCH" {
        cmd.args(["--data-binary", "@-"]);
    }
    cmd.arg(&url);
    cmd.stdin(if body.is_empty() { Stdio::null() } else { Stdio::piped() });
    cmd.stdout(Stdio::piped()).stderr(Stdio::null());
    let mut child = match cmd.spawn() { Ok(c) => c, Err(_) => return err("无法启动 curl") };
    if !body.is_empty() {
        if let Some(mut sin) = child.stdin.take() {
            if sin.write_all(body).is_err() { return err("请求体写入失败"); }
        }
    }
    let out = match child.wait_with_output() { Ok(o) => o, Err(_) => return err("代理请求失败") };
    if !out.status.success() { return err("在线服务暂时不可用"); }
    split_meta(out.stdout)
}

/// curl's -w trailer carries the remote status/content-type past the body.
fn split_meta(stdout: Vec<u8>) -> (u16, String, Vec<u8>) {
    let marker = b"\n__DV_META__";
    let at = stdout.windows(marker.len()).rposition(|w| w == marker).unwrap_or(stdout.len());
    let payload = if at == stdout.len() { stdout.clone() } else { stdout[..at].to_vec() };
    let meta = if at == stdout.len() { "".to_string() }
        else { String::from_utf8_lossy(&stdout[at + marker.len()..]).to_string() };
    let mut it = meta.splitn(2, '|');
    let code = it.next().unwrap_or("200").trim().to_string();
    let ctype = it.next().unwrap_or("").trim().to_string();
    let mime = if ctype.is_empty() { "application/json".to_string() } else { ctype };
    (code.parse().unwrap_or(200), mime, payload)
}

/// Desktop WebDAV proxy: the hosted /api/dav-proxy refuses private IPs, which
/// is exactly where a desktop user's NAS lives. curl talks straight to the
/// user's own server, so LAN/self-hosted storage works without a relay.
fn proxy_dav(body: &[u8]) -> (u16, String, Vec<u8>) {
    let fail = |msg: &str| (502u16, "application/json".to_string(), json!({ "error": msg }).to_string().into_bytes());
    let v: Value = match serde_json::from_slice(body) { Ok(v) => v, Err(_) => return fail("bad dav-proxy payload") };
    if v.get("probe").and_then(|x| x.as_bool()) == Some(true) {
        return (200, "application/json".to_string(), b"{\"ok\":true}".to_vec());
    }
    let url = v.get("u").and_then(|x| x.as_str()).unwrap_or("");
    // Trust boundary: only the two schemes the provider itself can produce.
    if !(url.starts_with("http://") || url.starts_with("https://")) { return fail("invalid dav target"); }
    let verb = v.get("m").and_then(|x| x.as_str()).unwrap_or("GET");
    let mut cmd = Command::new("curl");
    cmd.args(["-sS", "--max-time", "15", "-X", verb, "-w", "\n__DV_META__%{http_code}|%{content_type}"]);
    if let Some(h) = v.get("h").and_then(|x| x.as_object()) {
        for (k, val) in h {
            if let Some(sv) = val.as_str() { cmd.arg("-H").arg(format!("{k}: {sv}")); }
        }
    }
    let payload = v.get("b").and_then(|x| x.as_str()).unwrap_or("").as_bytes().to_vec();
    if !payload.is_empty() { cmd.args(["--data-binary", "@-"]); }
    cmd.arg(url);
    cmd.stdin(if payload.is_empty() { Stdio::null() } else { Stdio::piped() });
    cmd.stdout(Stdio::piped()).stderr(Stdio::null());
    let mut child = match cmd.spawn() { Ok(c) => c, Err(_) => return fail("无法启动 curl") };
    if !payload.is_empty() {
        if let Some(mut sin) = child.stdin.take() {
            if sin.write_all(&payload).is_err() { return fail("请求体写入失败"); }
        }
    }
    let out = match child.wait_with_output() { Ok(o) => o, Err(_) => return fail("代理请求失败") };
    if !out.status.success() { return fail("WebDAV 服务不可达"); }
    split_meta(out.stdout)
}

fn respond(stream: &mut TcpStream, mime: &str, body: &[u8]) -> std::io::Result<()> {
    respond_status(stream, 200, mime, body)
}

/// The proxy needs the UPSTREAM status: WebDAV's MOVE must answer 201/204 and
/// a missing file must answer 404, or the provider misreads the result.
fn respond_status(stream: &mut TcpStream, status: u16, mime: &str, body: &[u8]) -> std::io::Result<()> {
    let reason = match status {
        201 => "Created", 204 => "No Content", 207 => "Multi-Status",
        400 => "Bad Request", 401 => "Unauthorized", 403 => "Forbidden",
        404 => "Not Found", 405 => "Method Not Allowed", 409 => "Conflict",
        412 => "Precondition Failed", 500 => "Internal Server Error",
        502 => "Bad Gateway", 503 => "Service Unavailable",
        _ => "OK",
    };
    let head = format!(
        "HTTP/1.1 {status} {reason}\r\nContent-Type: {mime}\r\nContent-Length: {}\r\nCache-Control: no-cache\r\nConnection: close\r\n\r\n",
        body.len()
    );
    stream.write_all(head.as_bytes())?;
    stream.write_all(body)?;
    Ok(())
}

fn mime_of(path: &str) -> &'static str {
    let ext = path.rsplit('.').next().unwrap_or("");
    match ext {
        "html" | "htm" => "text/html; charset=utf-8",
        "js" | "mjs" => "text/javascript; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "json" => "application/json",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "ico" => "image/x-icon",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "ttf" => "font/ttf",
        "otf" => "font/otf",
        "txt" => "text/plain; charset=utf-8",
        "mp4" => "video/mp4",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        _ => "application/octet-stream",
    }
}
